<?php require_once 'config.php'; require_once 'lang.php'; $langue=$_COOKIE['langue']??'fr'; $titre_page=t('nav_tableau'); $recherche=trim($_GET['recherche']??''); if($recherche!==''){ $s=$connexion->prepare('SELECT * FROM employes WHERE nom LIKE ? OR prenom LIKE ? OR poste LIKE ? OR matricule LIKE ? ORDER BY id DESC'); $m="%$recherche%"; $s->bind_param('ssss',$m,$m,$m,$m); $s->execute(); $r=$s->get_result(); }else $r=$connexion->query('SELECT * FROM employes ORDER BY id DESC'); $total=$connexion->query('SELECT COUNT(*) n FROM employes')->fetch_assoc()['n']; include 'inclure_entete.php'; ?><header><h1><?=t('bonjour')?></h1><p><?=t('sous_titre_dashboard')?></p><a class="btn" href="ajouter.php"><?=t('btn_ajouter')?></a></header><form class="recherche"><input name="recherche" value="<?=htmlspecialchars($recherche)?>" placeholder="<?=t('rechercher_placeholder')?>"><button><?=t('btn_rechercher')?></button></form><section class="carte"><h2><?=t('employes_titre')?> (<?=$total?>)</h2><table><tr><th><?=t('col_employe')?></th><th><?=t('col_matricule')?></th><th><?=t('col_poste')?></th><th><?=t('col_salaire')?></th><th><?=t('col_actions')?></th></tr><?php while($e=$r->fetch_assoc()): ?><tr><td><?=htmlspecialchars($e['prenom'].' '.$e['nom'])?></td><td><?=htmlspecialchars($e['matricule'])?></td><td><?=htmlspecialchars($e['poste'])?></td><td><?=number_format($e['salaire'],2,',',' ')?></td><td><a href="modifier.php?id=<?=$e['id']?>"><?=t('btn_modifier')?></a> <a href="confirmer_suppression.php?id=<?=$e['id']?>"><?=t('btn_supprimer')?></a></td></tr><?php endwhile; ?></table></section><?php include 'inclure_pied.php'; ?>
